using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class Portsea : LayoutBase
{
    public Portsea()
    {
        Name = LayoutNamesEnums.Portsea;
        Description = "Built to a scale of 3mm to 1 foot in response to the 50th anniversary celebrations of the 3mm Society, Portsea is a portrayal of the Portsmouth Town and Harbour stations and their approaches as operated in the post nationalisation era, using locomotives and rolling stock typical of the period. Various features of the locality have been incorporated, specifically the war memorial, Commercial Road bridge, the Dockyard gates and part of the Semaphore Tower building, and an adaptation of the Royal Naval dockyard is included with some modeller's licence, complete with its internal rail system and access to the national network from the town station. Part of the challenge was to construct the layout from models and kits that can be bought from the local model shop. The track is from the Peco HOm range - a little coarse for 3mm 1:100 scale, but it matches the original 12mm gauge developed by Triang. Buildings are all made from adapted continental kits and the terminus station complex is scratch built from plasticard, although the station building and footbridge are adapted from Triang models. As there are no ready-to-run British outline locomotives and rolling stock in the scale, all those operated on the layout are built from scratch or from kits, with a few modified Triang items.";
    }
}
